"""Return fixed Morgan fingerprints as molecular embedding vectors."""

from model_benchmarks.processors import ModelBatch
from model_benchmarks.processors.morgan import MORGAN_BITS, MORGAN_RADIUS

from . import EmbeddingResult


class MorganEmbedder:
    """Return binary ECFP4 vectors generated by the Morgan processor."""

    model_name = "morgan"
    modality = "molecule"
    dimension = MORGAN_BITS
    pooling = "none (Morgan ECFP4 bit vector)"

    def __init__(self, checkpoint_path=None, device: str = "cpu"):
        if checkpoint_path is not None:
            raise ValueError("Morgan fingerprints have no checkpoint")

        import torch

        if torch.device(device).type != "cpu":
            raise ValueError("Morgan fingerprints run on CPU")
        self._torch = torch

    def encode(self, batch: ModelBatch) -> EmbeddingResult:
        rows = batch.inputs.get("fingerprints")
        if not isinstance(rows, list):
            raise TypeError("Morgan fingerprints must be a list of rows")
        if len(rows) != len(batch.record_ids):
            raise ValueError("Morgan fingerprint rows do not match record_ids")
        if not rows:
            raise ValueError("Morgan cannot encode an empty batch")
        if any(len(row) != self.dimension for row in rows):
            raise ValueError(f"every Morgan row must contain {self.dimension} bits")

        embeddings = self._torch.tensor(rows, dtype=self._torch.float32)
        if not self._torch.all((embeddings == 0) | (embeddings == 1)):
            raise ValueError("Morgan fingerprints must contain only zero or one")

        return EmbeddingResult(
            embeddings=embeddings,
            record_ids=list(batch.record_ids),
            model_name=self.model_name,
            checkpoint=None,
            dimension=self.dimension,
            pooling=self.pooling,
            metadata={
                "modality": self.modality,
                "processor_mode": batch.metadata.get("processor_mode"),
                "representation": "morgan_ecfp4",
                "radius": MORGAN_RADIUS,
                "n_bits": MORGAN_BITS,
                "learned": False,
            },
        )


__all__ = ["MorganEmbedder"]
